def emit(self, record):
        ''' Takes the logger record and does something with it

        In this case it will first print it to stdout if the level is below
        ERROR or stderr for ERROR and above.
        '''

        # This checks for level equal or above ERROR and prints to stderr,
        # stdout otherwise
        header = self.create_general_header(record.levelno, record)

        for line in format_message(record).splitlines():
            print(header, line, file=sys.stdout, flush=True)

        # This checks for exception, always print to stderr
        if record.exc_info:
            header = self.create_general_header(EXC_LEVEL, record)
            if isinstance(record.exc_info, list):
                lines = record.exc_info
            else:
                lines = "".join(traceback.format_exception(*record.exc_info)).splitlines()

            for line in lines:
                print(header, line, file=sys.stdout, flush=True)

std::vector<uint32_t> GetOvxTransposePerm(const std::vector<uint32_t>& perm) {
  std::vector<uint32_t> perm_out(perm.rbegin(), perm.rend());
  std::vector<uint32_t> perm_in, ovx_perm;
  for (int i = perm.size() - 1; i >= 0; i--) {
    perm_in.push_back(i);
  }
  for (auto o : perm_out) {
    for (int i = 0; i < perm_in.size(); i++) {
      if (o == perm_in[i]) {
        ovx_perm.push_back(i);
        break;
      }
    }
  }

  return ovx_perm;
}

func (db *DBaseFile) readTerminator() (err error) {
	err = db.checkOffset(db.offsets.fieldEnd, `starting to read terminator character`)
	if err != nil {
		return err
	}

	terminator := make([]byte, 1)
	_, err = db.r.Read(terminator)
	if err != nil {
		return err
	}

	if terminator[0] != TerminatorCharacter {
		return fmt.Errorf(`invalid terminator: %#v`, terminator)
	}

	err = db.checkOffset(db.offsets.terminatorEnd, `after terminator character`)
	if err != nil {
		return err
	}

	return nil
}

