void calculateFOV(float h_fov, float v_fov, FOV_indices& FOV,
                  float yaw_deg_histogram_frame, float pitch_deg) {
  PolarPoint max_angle(pitch_deg + v_fov / 2.0f,
                       yaw_deg_histogram_frame + h_fov / 2.0f, 1.f);
  PolarPoint min_angle(pitch_deg - v_fov / 2.0f,
                       yaw_deg_histogram_frame - h_fov / 2.0f, 1.f);
  Eigen::Vector2i max_ind = polarToHistogramIndex(max_angle, ALPHA_RES);
  Eigen::Vector2i min_ind = polarToHistogramIndex(min_angle, ALPHA_RES);

  FOV.e_idx_max = max_ind.y();
  FOV.e_idx_min = min_ind.y();

  // indices not wrapped
  if (max_ind.x() > min_ind.x()) {
    for (int i = min_ind.x(); i <= max_ind.x(); i++) {
      FOV.z_idx_vec.push_back(i);
    }
  }

  // indices wrapped
  if (min_ind.x() > max_ind.x()) {
    for (int i = 0; i <= max_ind.x(); i++) {
      FOV.z_idx_vec.push_back(i);
    }
    for (int i = min_ind.x(); i < GRID_LENGTH_Z; i++) {
      FOV.z_idx_vec.push_back(i);
    }
  }
}

func (z PolyLineZ) read(r io.ReadSeeker) (retrec ShapeTypeI, err error) {
	var rawrec struct {
		Box       Box
		NumParts  uint32
		NumPoints uint32
	}
	err = binary.Read(r, binary.LittleEndian, &rawrec)
	if err != nil {
		return nil, xerrors.Errorf(`couldn't read raw poly line header: %w`, err)
	}

	z.Box = rawrec.Box
	z.NumParts = rawrec.NumParts
	z.NumPoints = rawrec.NumPoints

	z.Parts = make([]uint32, z.NumParts)
	err = binary.Read(r, binary.LittleEndian, &z.Parts)
	if err != nil {
		return nil, xerrors.Errorf(`parts: %w`, err)
	}

	z.Points = make([]Point, z.NumPoints)
	err = binary.Read(r, binary.LittleEndian, &z.Points)
	if err != nil {
		return nil, xerrors.Errorf(`points: %w`, err)
	}

	err = binary.Read(r, binary.LittleEndian, &z.ZRange)
	if err != nil {
		return nil, xerrors.Errorf(`zrange: %w`, err)
	}

	z.ZArray = make([]float64, z.NumPoints)
	err = binary.Read(r, binary.LittleEndian, &z.ZArray)
	if err != nil {
		return nil, xerrors.Errorf(`Z-Array: %w`, err)
	}

	err = binary.Read(r, binary.LittleEndian, &z.MRange)
	if err != nil {
		return nil, xerrors.Errorf(`M Range: %w`, err)
	}

	z.MArray = make([]float64, z.NumPoints)
	err = binary.Read(r, binary.LittleEndian, &z.MArray)
	if err != nil {
		return nil, xerrors.Errorf(`M-Array: %w`, err)
	}

	return z, nil
}

private boolean initializeSerialPort() {
        try {
            CommPortIdentifier portId = null;
            Enumeration portEnum = CommPortIdentifier.getPortIdentifiers();

            // Enumerate system ports and try connecting to Arduino over each
            System.out.println( "Trying:");
            while (portId == null && portEnum.hasMoreElements()) {

                // Iterate through your host computer's serial port IDs
                CommPortIdentifier currPortId = (CommPortIdentifier) portEnum.nextElement();
                System.out.println( "   port" + currPortId.getName() );
                for (String portName : PORT_NAMES) {
                    if ( currPortId.getName().equals(portName)
                            || currPortId.getName().startsWith(portName)) {

                        // Try to connect to the Arduino on this port
                        //
                        // Open serial port
                        serialPort = (SerialPort)currPortId.open(appName, TIME_OUT);
                        portId = currPortId;
                        System.out.println( "Connected on port" + currPortId.getName() );
                        break;
                    }
                }
            }

            if (portId == null || serialPort == null) {
                System.out.println("Oops... Could not connect to Arduino");
                return false;
            }


            // set port parameters
            serialPort.setSerialPortParams(DATA_RATE,
                    SerialPort.DATABITS_8,
                    SerialPort.STOPBITS_1,
                    SerialPort.PARITY_NONE);


            // add event listeners
            serialPort.addEventListener(this);
            serialPort.notifyOnDataAvailable(true);

            // Give the Arduino some time
            try {
                Thread.sleep(2000);
            } catch (InterruptedException ie) {
                ie.printStackTrace();
            }

            return true;

        } catch ( Exception e ) {
            e.printStackTrace();
        }

        return false;
    }

