public void sendMsg(Byte msg, Byte base) {
        //System.out.println("\n Single Motor Update");
        Byte byteMsg = 0;

        if( base == ALLOFF) {
            System.out.println("All motors off!");
            sendToSerialPort(ALLOFF);
            return;
        }

        //Left Motor
        if( base == MOTOR_BASE_LEFT) {
            byteMsg = (byte)(base + msg);
