function ngApply(controller, cb) {
	var scope = ngGetScope(controller);
	if (!scope) {
		console.error('Cannot find controler', controller, 'when attempting to apply code');
		return;
	}

	if (!scope.$$phase) {
		scope.$apply(function() {
			cb(scope);
		});
	} else {
		setTimeout(function() {
			scope.$apply(function() {
				cb(scope);
			});
		}, 0);
	}
}

